<script setup>
import {ref,computed} from 'vue';
import {Copy,Plus,Trash2,ArrowUp,ArrowDown,Image,ExternalLink} from 'lucide-vue-next';
import VideoWorkflowNav from './VideoWorkflowNav.vue';
import WorkspaceHeader from './WorkspaceHeader.vue';
import WorkflowAlerts from './WorkflowAlerts.vue';
import LibraryPreview from './LibraryPreview.vue';
import {useVideoWorkflow,downloadText} from '../useVideoWorkflow.js';
import {normalizeWorkflow,chapterErrors,chaptersText,chaptersFromConductor} from '../videoWorkflow.js';
const props=defineProps({repository:Object,videoId:String});const emit=defineEmits(['back','workshop','open-creation','open-notes']);
const {project,data,error,loading,saving,dirty,recovery,storageError,load,save,flush,recover,exportDraft}=useVideoWorkflow(props,'publication');defineExpose({flush});
const notice=ref(''),templateUndo=ref(null),chapterUndo=ref(null),templateBusy=ref(false);
const thumbnails=computed(()=>project.value?.creations.filter(c=>c.app==='thumbnails')||[]),thumbnail=computed(()=>thumbnails.value.find(c=>c.id===data.value?.thumbnailId));
const issues=computed(()=>chapterErrors(data.value?.chapters||[])),formatted=computed(()=>chaptersText(data.value?.chapters||[]));
async function go(action){try{await flush();action();}catch{}}
async function copy(value,name){try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(value);notice.value=name+' copié.';}catch{notice.value='La copie n’est pas disponible ici. Sélectionne le texte du champ puis utilise Ctrl/⌘ C.';}}
function addChapter(){if(data.value.chapters.length<100)data.value.chapters.push({id:crypto.randomUUID(),sequenceId:'',time:'',title:''});}
function moveChapter(i,delta){const to=i+delta;if(to<0||to>=data.value.chapters.length)return;const [row]=data.value.chapters.splice(i,1);data.value.chapters.splice(to,0,row);}
async function fromConductor(){try{const latest=await props.repository.get(props.videoId),sequences=normalizeWorkflow(latest?.workflow).conductor.sequences;if(!sequences.length){notice.value='Le conducteur ne contient pas encore de parties.';return;}chapterUndo.value=structuredClone(JSON.parse(JSON.stringify(data.value.chapters)));data.value.chapters=chaptersFromConductor(sequences,data.value.chapters);notice.value='Titres repris du conducteur. Renseigne les horaires du montage final.';}catch(e){error.value=e.message;}}
function removeChapter(i){chapterUndo.value=JSON.parse(JSON.stringify(data.value.chapters));data.value.chapters.splice(i,1);}
const templateKey=()=>`frame-publication-template:${project.value.playlist||'sans-playlist'}`;
async function saveTemplate(){templateBusy.value=true;try{await props.repository.setSetting(templateKey(),{description:data.value.description});notice.value='Modèle de description enregistré pour '+(project.value.playlist||'Sans playlist')+'.';}catch{notice.value='Le modèle n’a pas pu être enregistré.';}finally{templateBusy.value=false;}}
async function applyTemplate(){templateBusy.value=true;try{const template=await props.repository.getSetting(templateKey());if(typeof template?.description!=='string'){notice.value='Aucun modèle pour cette playlist. Écris une description puis enregistre-la comme modèle.';return;}templateUndo.value=data.value.description;data.value.description=template.description.slice(0,20000);notice.value='Modèle appliqué à cette vidéo.';}catch{notice.value='Le modèle n’a pas pu être chargé.';}finally{templateBusy.value=false;}}
function exportPublication(){downloadText('publication.txt',`TITRE\n${data.value.title}\n\nDESCRIPTION\n${data.value.description}\n\nCHAPITRES\n${formatted.value}\n\nCOMMENTAIRE ÉPINGLÉ\n${data.value.comment}`);}
</script>
<template>
 <main class="production-app publication-app" @keydown.ctrl.s.prevent="save().catch(()=>{})" @keydown.meta.s.prevent="save().catch(()=>{})">
  <WorkspaceHeader title="Publication" back-label="Vidéo" @back="go(()=>emit('back'))"><template #context><span class="creation-context-name">{{project?.name}}</span><span class="production-test">TEST</span></template><template #file><button @click="save().catch(()=>{})">Enregistrer · Ctrl S</button><button :disabled="!data" @click="exportPublication">Exporter les textes de publication</button></template><template #actions><span class="save-state" role="status">{{saving?'Sauvegarde…':dirty?'Modifications en attente':'Enregistré'}}</span></template></WorkspaceHeader>
  <WorkflowAlerts :error="error" :storage-error="storageError" :recovery="!!recovery" @retry="save().catch(()=>{})" @reload="load" @export="exportDraft" @recover="recover"/>
  <p v-if="loading" class="production-loading">Ouverture de la publication…</p>
  <template v-else-if="project&&data">
   <VideoWorkflowNav active="publication" @navigate="name=>go(()=>name==='notes'?emit('open-notes'):emit('workshop',name))"/>
   <p v-if="notice" class="publication-feedback" role="status">{{notice}}</p>
   <div class="publication-layout">
    <section class="publication-writing"><article class="production-card publication-title"><div class="publication-field-label"><label for="publication-title">Titre</label><button class="icon-btn" title="Copier le titre" aria-label="Copier le titre" :disabled="!data.title.trim()" @click="copy(data.title,'Titre')"><Copy :size="16"/></button></div><input id="publication-title" v-model="data.title" aria-label="Titre YouTube" maxlength="200" :placeholder="project.name"><button v-if="!data.title" class="text-action" @click="data.title=project.name">Utiliser le nom de la vidéo</button></article>
     <article class="production-card publication-texts">
      <section><div class="publication-field-label"><label for="publication-description">Description</label><button class="icon-btn" :disabled="!data.description.trim()" title="Copier : Description" aria-label="Copier : Description" @click="copy(data.description,'Description')"><Copy :size="16"/></button></div><textarea id="publication-description" v-model="data.description" aria-label="Description YouTube" rows="6" maxlength="20000" placeholder="Dans cette vidéo…"/><div class="description-template"><span>Modèle · {{project.playlist||'Sans playlist'}}</span><button class="btn" :disabled="templateBusy||!data.description.trim()" @click="saveTemplate">Enregistrer comme modèle</button><button class="btn" :disabled="templateBusy" @click="applyTemplate">Utiliser le modèle</button><button v-if="templateUndo!==null" class="text-action" @click="data.description=templateUndo;templateUndo=null">Annuler l’application du modèle</button></div></section>
      <section><div class="publication-field-label"><span id="chapters-label">Chapitres</span><button class="icon-btn" :disabled="!data.chapters.length||issues.length>0" title="Copier : Chapitres" aria-label="Copier : Chapitres" @click="copy(formatted,'Chapitres')"><Copy :size="16"/></button></div><div class="production-actions chapter-actions"><button class="btn" @click="fromConductor">Reprendre les titres du conducteur</button><button class="btn" :disabled="data.chapters.length>=100" @click="addChapter"><Plus :size="14"/>Ajouter</button><button v-if="chapterUndo" class="text-action" @click="data.chapters=chapterUndo;chapterUndo=null">Annuler la dernière modification de liste</button></div><div v-if="!data.chapters.length" class="production-inline-empty">Commence depuis le conducteur ou ajoute tes propres chapitres.</div><div v-for="(chapter,i) in data.chapters" :key="chapter.id" class="publication-chapter"><span>{{String(i+1).padStart(2,'0')}}</span><input v-model="chapter.time" :aria-label="'Horaire du chapitre '+(i+1)" placeholder="00:00" maxlength="12"><input v-model="chapter.title" :aria-label="'Titre du chapitre '+(i+1)" placeholder="Titre du chapitre" maxlength="200"><div><button class="icon-btn" :disabled="i===0" :aria-label="'Monter le chapitre '+(i+1)" @click="moveChapter(i,-1)"><ArrowUp :size="13"/></button><button class="icon-btn" :disabled="i===data.chapters.length-1" :aria-label="'Descendre le chapitre '+(i+1)" @click="moveChapter(i,1)"><ArrowDown :size="13"/></button><button class="icon-btn" :aria-label="'Supprimer le chapitre '+(i+1)" @click="removeChapter(i)"><Trash2 :size="14"/></button></div></div><div v-if="issues.length" class="chapter-issues" role="status"><p v-for="issue in issues.slice(0,4)" :key="issue">{{issue}}</p><p v-if="issues.length>4">Et {{issues.length-4}} autres champs à compléter.</p></div><details v-if="data.chapters.length" class="chapter-copy-preview"><summary>Voir le texte à copier</summary><textarea :value="formatted" aria-label="Chapitres formatés" readonly rows="4"/></details></section>
      <section><div class="publication-field-label"><label for="publication-comment">Commentaire épinglé</label><button class="icon-btn" :disabled="!data.comment.trim()" title="Copier : Commentaire épinglé" aria-label="Copier : Commentaire épinglé" @click="copy(data.comment,'Commentaire')"><Copy :size="16"/></button></div><textarea id="publication-comment" v-model="data.comment" aria-label="Commentaire épinglé" rows="6" maxlength="20000" placeholder="Les exemples et ressources de la vidéo…"/></section>
     </article>
    </section>
    <aside class="publication-visual"><article class="production-card"><div class="publication-field-label"><span>Miniature</span><Image :size="18"/></div><label class="production-field">Variante existante<select v-model="data.thumbnailId" aria-label="Miniature de publication"><option value="">Choisir une miniature</option><option v-for="row in thumbnails" :key="row.id" :value="row.id">{{row.name}}</option></select></label><div v-if="thumbnail" :key="thumbnail.id" class="publication-thumbnail"><LibraryPreview :repository="repository" :creation="thumbnail"/><h3>{{data.title||project.name}}</h3><button class="btn" @click="go(()=>emit('open-creation',videoId,thumbnail.app,thumbnail.id))">Ouvrir dans Miniatures<ExternalLink :size="14"/></button></div><div v-else class="production-inline-empty"><Image :size="30"/><p>{{data.thumbnailId?'Cette miniature a été retirée de la vidéo.':'Retrouve ici les miniatures de cette vidéo.'}}</p><button v-if="!thumbnails.length" class="btn" @click="go(()=>emit('back'))">Créer depuis la fiche vidéo</button></div></article></aside>
   </div>
  </template>
 </main>
</template>
